explain (analyze, buffers) select d.device_id, d.role, d.vendor_hint, d.enrollment_state, d.backup_target, coalesce(d.observed_hostname, dc.display_name) as observed_hostname, coalesce(d.observed_model, dc.model, c_parent.model) as observed_model, coalesce(d.observed_software_version, dc.software_version, c_parent.software_version) as observed_software_version, coalesce(d.observed_ha_role, inv_ha.role) as observed_ha_role, coalesce(c_parent.display_name, d.cluster_member_ref, dc.cluster_reference) as cluster_member_ref, (d.ha_pair_claim is not null and d.cluster_member_ref is null) as ha_peer_unconfirmed, coalesce(vs_info.virtual_systems, inv_run.virtual_systems) as virtual_systems, latest_job.state as latest_job_state, latest_job.job_type as latest_job_type, latest_job.terminal_reason as latest_job_terminal_reason, ep.address_ref as management_ip, if_ips.interface_ips as ip_addresses from devices d left join lateral (     select display_name, model, software_version, cluster_reference, parent_candidate_id, candidate_id from discovery_candidate c     where ((c.vendor || '|' || coalesce(c.owning_domain, '') || '|' || c.stable_identifier) = d.discovery_match_key        or (c.vendor || '|' || c.stable_identifier) = d.discovery_match_key        or c.stable_identifier = d.recorded_identity_primary)     order by (c.parent_candidate_id is null) desc     limit 1 ) dc on true left join lateral (     select display_name, model, software_version from discovery_candidate c2     where c2.candidate_id = dc.parent_candidate_id        or c2.stable_identifier = coalesce(d.cluster_member_ref, dc.cluster_reference)     limit 1 ) c_parent on true left join lateral (     select string_agg(distinct substring(c_vs.display_name from length(dc.display_name) + 2), ', ' order by substring(c_vs.display_name from length(dc.display_name) + 2)) as virtual_systems     from discovery_candidate c_vs     where dc.display_name is not null       and c_vs.display_name collate "C" > dc.display_name collate "C"       and c_vs.display_name collate "C" < (dc.display_name || chr(1114111)) collate "C"       and c_vs.display_name like dc.display_name || '_%' ) vs_info on true left join lateral (     select virtual_systems from device_inventory_run dir where dir.device_id = d.device_id order by collected_at desc limit 1 ) inv_run on true left join lateral (     select h.role from device_inventory_run r2 join device_inventory_ha h on h.run_id = r2.run_id     where r2.device_id = d.device_id and h.context = 'physical' order by r2.collected_at desc limit 1 ) inv_ha on true left join lateral (     select address_ref from endpoints ep where ep.device_id = d.device_id order by ep.created_at asc limit 1 ) ep on true left join lateral (     select state, job_type, terminal_reason from jobs j where j.target_device_id = d.device_id order by j.submitted_at desc limit 1 ) latest_job on true left join lateral (     select string_agg(distinct dia.address, ' ') as interface_ips     from (select run_id from device_inventory_run r where r.device_id = d.device_id order by r.collected_at desc limit 1) latest_r     join device_interface di on di.run_id = latest_r.run_id     join device_interface_address dia on dia.interface_id = di.interface_id ) if_ips on true order by d.created_at desc, d.device_id;
explain (analyze, buffers) select d.device_id, coalesce(d.observed_hostname, dc.display_name) as observed_hostname, coalesce(c_parent.display_name, d.cluster_member_ref, dc.cluster_reference) as cluster_member_ref from devices d left join lateral (     select display_name, cluster_reference, parent_candidate_id from discovery_candidate c     where ((c.vendor || '|' || coalesce(c.owning_domain, '') || '|' || c.stable_identifier) = d.discovery_match_key        or (c.vendor || '|' || c.stable_identifier) = d.discovery_match_key        or c.stable_identifier = d.recorded_identity_primary)     order by (c.parent_candidate_id is null) desc     limit 1 ) dc on true left join lateral (     select display_name from discovery_candidate c2     where c2.candidate_id = dc.parent_candidate_id        or c2.stable_identifier = coalesce(d.cluster_member_ref, dc.cluster_reference)     limit 1 ) c_parent on true order by d.created_at asc, d.device_id;
explain (analyze, buffers) with unit_keys as (select vendor,cluster_ref,vs_id from failover_approval union select vendor,cluster_ref,vs_id from failover_run) select k.vendor,k.cluster_ref,k.vs_id, exists(select 1 from failover_approval a where a.vendor=k.vendor and a.cluster_ref=k.cluster_ref and a.vs_id is not distinct from k.vs_id and a.revoked_at is null and a.request_revision is not null and a.approved_by is not null and a.policy_version=1 and not exists(select 1 from failover_run used where used.approval_id=a.approval_id) and a.window_from<=now() and now()<a.window_until) as active_window, r.state,r.outcome,r.scheduled_for from unit_keys k left join lateral (select state,outcome,scheduled_for from failover_run r where r.vendor=k.vendor and r.cluster_ref=k.cluster_ref and r.vs_id is not distinct from k.vs_id order by scheduled_for desc limit 1) r on true;
explain (analyze, buffers) with latest as (
    select distinct on (vendor,cluster_ref,coalesce(vs_id,''))
        run_id,cluster_ref,vs_id,vendor,outcome,finished_at,failed_check,message
    from failover_run where run_kind='READINESS' and state in ('DONE','STOPPED')
    order by vendor,cluster_ref,coalesce(vs_id,''),finished_at desc
)
select r.cluster_ref,r.vs_id,r.vendor,r.outcome,r.finished_at,r.failed_check,r.message,
    coalesce(c.checks,'[]'::jsonb) as checks
from latest r left join lateral (
    select jsonb_agg(jsonb_build_object(
        'memberRef',c.member_ref,'observedAt',c.observed_at,'checkNo',c.check_no,
        'status',c.status,'derived',c.derived) order by c.check_no,c.member_ref) as checks
    from failover_check_result c where c.run_id=r.run_id and c.phase='pre'
) c on true;
